package org.jsoup.nodes;

import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.internal.StringUtil;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.jspecify.annotations.Nullable;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
 * form to easily be submitted.
 */
public class FormElement extends Element {
    private final Elements linkedEls = new Elements();
    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));
    // the form-listed elements (HTML spec), that can be associated with a form, either as a descendant or via a form attribute
    private static final Evaluator listed = Selector.evaluatorOf(StringUtil.join(FormListedTags, ", "));
    private static final String[] FormListedTags = {
        "button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"
    };
    private static final Evaluator listedWithFormAttr = Selector.evaluatorOf(StringUtil.join(FormListedTags, "[form], ") + "[form]");

    /**
     * Create a new, standalone form element.
     *
     * @param tag        tag of this element
     * @param baseUri    the base URI
     * @param attributes initial attributes
     */
    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
        super(tag, baseUri, attributes);
    }

    /**
     * Get the list of form control elements associated with this form.
     * @return form controls associated with this element.
     */
    public Elements elements() {
        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
        Elements els = select(submittable); // current form children
        for (Element linkedEl : linkedEls) {
            if (linkedEl.ownerDocument() != null && !els.contains(linkedEl)) {
                els.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
            }
        }

        return els;
    }

    /**
     * Get the form-listed elements (controls) currently associated with this form, in final document order. A control
     * is associated if it is a descendant of this form, or if it is outside this form and carries a {@code form}
     * attribute whose value matches this form's id. Controls pointing at another form, an unknown form id, and
     * controls that are no longer attached to this document, are not included. A control matched through both paths
     * is included only once.
     */
    private Elements associatedControls() {
        Document doc = ownerDocument();
        Elements controls = new Elements();

        // descendants that are listed for form association
        for (Element el : select(listed)) {
            if (belongsToThisForm(el)) controls.add(el);
        }

        // controls outside the form, associated by a form="id" attribute
        if (doc != null) {
            String id = id();
            if (!id.isEmpty()) {
                for (Element el : doc.select(listedWithFormAttr)) {
                    if (el.ownerDocument() == doc && belongsToThisForm(el) && !controls.contains(el))
                        controls.add(el);
                }
            }
            controls.sort(DocumentOrder);
        }
        return controls;
    }

    /** A listed control belongs to this form if it has no form attribute (and so associates by ancestry), or its form
     * attribute resolves to this form. */
    private boolean belongsToThisForm(Element el) {
        String formOwner = el.attr("form");
        if (formOwner.isEmpty()) {
            return el.insideFormAncestor(this);
        }
        Document doc = ownerDocument();
        return doc != null && doc.getElementById(formOwner) == this;
    }

    // compares attached nodes by their position in the final document, in a pre-order traversal
    private static final Comparator<Element> DocumentOrder = (a, b) -> {
        if (a == b) return 0;
        ArrayList<Node> aPath = ancestorPath(a);
        ArrayList<Node> bPath = ancestorPath(b);
        int depth = Math.min(aPath.size(), bPath.size());
        for (int i = 0; i < depth; i++) {
            Node aAncestor = aPath.get(i);
            Node bAncestor = bPath.get(i);
            if (aAncestor != bAncestor)
                return Integer.compare(aAncestor.siblingIndex(), bAncestor.siblingIndex());
        }
        return Integer.compare(aPath.size(), bPath.size()); // one is an ancestor of the other
    };

    private static ArrayList<Node> ancestorPath(Node node) {
        ArrayList<Node> path = new ArrayList<>();
        Node current = node;
        while (current != null) {
            path.add(current);
            current = current.parentNode;
        }
        java.util.Collections.reverse(path);
        return path;
    }

    /**
     * Add a form control element to this form.
     * @param element form control to add
     * @return this form element, for chaining
     */
    public FormElement addElement(Element element) {
        linkedEls.add(element);
        return this;
    }

    @Override
    protected void removeChild(Node out) {
        super.removeChild(out);
        linkedEls.remove(out);
    }

    /**
     * Prepare to submit this form. A Connection object is created with the request set up from the form values. This
     * Connection will inherit the settings and the cookies (etc) of the connection/session used to request this Document
     * (if any), as available in {@link Document#connection()}
     <p>You can then set up other options (like user-agent, timeout, cookies), then execute it.</p>

     @return a connection prepared from the values of this form, in the same session as the one used to request it
     @throws IllegalArgumentException if the form's absolute action URL cannot be determined. Make sure you pass the
     document's base URI when parsing.
     */
    public Connection submit() {
        String action = hasAttr("action") ? absUrl("action") : baseUri();
        Validate.notEmpty(action, "Could not determine a form action URL for submit. Ensure you set a base URI when parsing.");
        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
                Connection.Method.POST : Connection.Method.GET;

        Document owner = ownerDocument();
        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
        return connection.url(action)
                .data(formData())
                .method(method);
    }

    /**
     * Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
     * list will not be reflected in the DOM.
     * @return a list of key vals
     */
    public List<Connection.KeyVal> formData() {
        ArrayList<Connection.KeyVal> data = new ArrayList<>();

        // iterate the associated form control elements, in final document order, and accumulate their values
        for (Element el: associatedControls()) {
            if (!el.tag().isFormSubmittable()) continue; // fieldset, button, output etc are listed, but not submittable
            if (el.hasAttr("disabled")) continue; // skip disabled form controls
            if (isDisabledFieldsetControl(el)) continue; // controls in a disabled fieldset, except in its first legend
            String name = el.attr("name");
            if (name.length() == 0) continue;
            String type = el.attr("type");

            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these

            if (el.nameIs("select")) {
                addSelectData(el, name, data);
            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
                // only add checkbox or radio if checked; value defaults to "on"
                if (el.hasAttr("checked")) {
                    final String val = el.val().length() >  0 ? el.val() : "on";
                    data.add(HttpConnection.KeyVal.create(name, val));
                }
            } else {
                data.add(HttpConnection.KeyVal.create(name, el.val()));
            }
        }
        return data;
    }

    private static void addSelectData(Element select, String name, ArrayList<Connection.KeyVal> data) {
        boolean multiple = select.hasAttr("multiple");
        Elements selected = new Elements();
        Elements enabled = new Elements();
        // options belong to the select if they are a direct child, or nested in an optgroup child
        for (Element child : select.children()) {
            if (child.nameIs("optgroup")) {
                if (!child.hasAttr("disabled")) {
                    for (Element option : child.children()) {
                        if (option.nameIs("option")) collectOption(option, selected, enabled);
                    }
                }
            } else if (child.nameIs("option")) {
                collectOption(child, selected, enabled);
            }
        }

        if (multiple) {
            // submit every enabled selected option, in option order; nothing if there are none
            for (Element option : selected) {
                data.add(HttpConnection.KeyVal.create(name, optionValue(option)));
            }
        } else {
            // single select: first enabled selected option, else the first enabled option
            Element option = !selected.isEmpty() ? selected.first() :
                (!enabled.isEmpty() ? enabled.first() : null);
            if (option != null)
                data.add(HttpConnection.KeyVal.create(name, optionValue(option)));
        }
    }

    private static void collectOption(Element option, Elements selected, Elements enabled) {
        if (option.hasAttr("disabled")) return;
        enabled.add(option);
        if (option.hasAttr("selected")) selected.add(option);
    }

    // an option's value is its value attribute, or its text content if that is absent
    private static String optionValue(Element option) {
        return option.hasAttr("value") ? option.attr("value") : option.text();
    }

    /**
     A control is excluded by a disabled fieldset if its nearest disabled fieldset ancestor is within this form's
     ownership and is not cancelled by the fieldset's first legend: the controls inside the first legend subtree of a
     disabled fieldset remain enabled. Nested fieldsets and sibling legends do not get the exception.
     */
    private static boolean isDisabledFieldsetControl(Element el) {
        Element parent = el.parent();
        while (parent != null) {
            if (parent.nameIs("fieldset") && parent.hasAttr("disabled")) {
                return true;
            }
            if (parent.nameIs("legend")) {
                // check if this legend is the first legend child of a disabled fieldset
                Element fieldset = parent.parent();
                if (fieldset != null && fieldset.nameIs("fieldset") && fieldset.hasAttr("disabled")
                        && isFirstLegend(parent, fieldset)) {
                    return false; // exempt: control is within the first legend of the disabled fieldset
                }
            }
            if (parent.nameIs("form")) break; // fieldset disabledness does not cross form ownership
            parent = parent.parent();
        }
        return false;
    }

    private static boolean isFirstLegend(Element legend, Element fieldset) {
        for (Element child : fieldset.children()) {
            if (child.nameIs("legend")) return child == legend;
        }
        return false;
    }

    @Override
    public FormElement clone() {
        return (FormElement) super.clone();
    }
}

