import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.Elements;
import org.jsoup.Connection;
import java.util.List;

public class FormProbe {
    static int fails = 0;
    static void check(String name, Object exp, Object act) {
        boolean ok = String.valueOf(exp).equals(String.valueOf(act));
        System.out.println((ok ? "PASS " : "FAIL ") + name + " => " + act + (ok ? "" : " (expected " + exp + ")"));
        if (!ok) fails++;
    }

    public static void main(String[] x) {
        // 1. external form attr + document order + same-name + ignores
        String html =
            "<form id=fA><input name=a value=1></form>" +
            "<form id=fB><input name=b value=2></form>" +
            "<input name=c value=3 form=fA>" +          // external, belongs to A
            "<input name=o1 value=x form=other>" +       // invalid id -> ignored
            "<input name=o2 value=x form=fB>" +          // external for B (inside body between)
            "<input name=nov value=x form=fA>" +         // no, has name; test no-name:
            "<input value=noname form=fA>" +
            "<select name=s form=fA><option>A1 selected><option>A2</select>";
        Document doc = Jsoup.parse(html);
        FormElement fA = (FormElement) doc.getElementById("fA");
        StringBuilder sb = new StringBuilder();
        for (Connection.KeyVal kv : fA.formData()) sb.append(kv).append("&");
        check("fA data order", "a=1&c=3&s=A1&", sb.toString());
        check("fB", "b=2&o2=x&", join(((FormElement)doc.getElementById("fB")).formData()));

        // dedup: foster control linked AND external form attr
        String h2 = "<table><tr><form id=g><input name=inside value=1></form><td><input name=out value=2 form=g></td></tr></table>";
        Document d2 = Jsoup.parse(h2);
        FormElement g = (FormElement) d2.getElementById("g");
        long outCount = g.formData().stream().filter(k -> k.key().equals("out")).count();
        check("foster+formattr dedup", 1L, outCount);
        check("foster linked included", "inside=1&out=2&", join(g.formData()));

        // disabled + fieldset legend rules
        String h3 = "<form id=h>" +
            "<input name=d value=1 disabled>" +
            "<fieldset disabled>" +
              "<legend><input name=leg value=2></legend>" +
              "<input name=fs value=3>" +
              "<legend><input name=leg2 value=4></legend>" +
              "<fieldset><input name=nested value=5></fieldset>" +
            "</fieldset>" +
            "<fieldset><input name=enabledfs value=6></fieldset>" +
            "</form>";
        FormElement h = (FormElement) Jsoup.parse(h3).getElementById("h");
        check("fieldset disabled", "leg=2&enabledfs=6&", join(h.formData()));

        // selects
        String h4 = "<form id=j>" +
            "<select name=single><option disabled>D<option value=S2 selected>S2<option selected>S3</select>" +
            "<select name=fallback><option disabled>D<option value=FB2>FB</select>" +
            "<select name=multi multiple><option value=M1 selected>M1<option disabled selected>M2<option value=M3 selected><optgroup disabled><option value=M4 selected></optgroup><option value=M5></select>" +
            "<select name=none multiple></select>" +
            "</form>";
        FormElement j = (FormElement) Jsoup.parse(h4).getElementById("j");
        check("selects", "single=S2&fallback=FB2&multi=M1&multi=M3&", join(j.formData()));

        // option value text fallback & empty value
        String h5 = "<form id=k><select name=sv><option selected>TextVal<option value selected><option value=empty-x></select></form>";
        check("option text value", "sv=TextVal&", join(((FormElement)Jsoup.parse(h5).getElementById("k")).formData()));

        // checkbox / radio defaults
        String h6 = "<form id=l><input type=checkbox name=cb checked><input type=checkbox name=cboff><input type=radio name=r checked value=RV><input type=radio name=r2></form>";
        check("checks", "cb=on&r=RV&", join(((FormElement)Jsoup.parse(h6).getElementById("l")).formData()));

        // text/textarea empty kept
        String h7 = "<form id=m><input name=t value=''><textarea name=ta></textarea><input name=h type=hidden value=''></form>";
        check("empty text vals", "t=&ta=&h=&", join(((FormElement)Jsoup.parse(h7).getElementById("m")).formData()));

        // empty form
        FormElement empty = (FormElement) Jsoup.parse("<form id=e></form>").getElementById("e");
        check("empty form", "[]", empty.formData().toString());
        check("empty form size", 0, empty.formData().size());

        // dynamic: delete / detach / reassign
        String h8 = "<form id=n><input name=k1 value=v1></form><input name=k2 value=v2 form=n>";
        Document d8 = Jsoup.parse(h8);
        FormElement n = (FormElement) d8.getElementById("n");
        check("dyn initial", "k1=v1&k2=v2&", join(n.formData()));
        d8.selectFirst("input[name=k1]").remove();
        check("dyn after remove", "k2=v2&", join(n.formData()));
        Element k2 = d8.selectFirst("input[name=k2]");
        k2.attr("form", "zzz");
        check("dyn after reassign invalid", "", join(n.formData()));
        d8.body().appendElement("form").attr("id", "p");
        k2.attr("form", "p");
        check("dyn reassign to other form", "", join(n.formData()));
        check("dyn other form gets it", "k2=v2&", join(((FormElement)d8.getElementById("p")).formData()));
        k2.removeAttr("form");
        check("dyn drop form attr, outside -> ignored", "", join(n.formData()));
        // move into form
        n.appendChild(k2);
        check("dyn moved into form", "k2=v2&", join(n.formData()));
        // detach form itself
        n.remove();
        check("detached form still reads linked children", "k2=v2&", join(n.formData()));

        // returned copy independence
        FormElement q = (FormElement) Jsoup.parse("<form id=q><input name=z value=1></form>").getElementById("q");
        List<Connection.KeyVal> d1 = q.formData();
        d1.clear();
        check("copy independence", "z=1&", join(q.formData()));

        // DOM unchanged after read
        String before = doc.toString();
        fA.formData();
        check("dom unchanged", before, doc.toString());
        check("doc still queryable", 2, doc.select("form").size());

        System.out.println(fails == 0 ? "ALL OK" : fails + " FAILURES");
        if (fails > 0) System.exit(1);
    }

    static String join(List<Connection.KeyVal> l) {
        StringBuilder s = new StringBuilder();
        for (Connection.KeyVal kv : l) s.append(kv).append("&");
        return s.toString();
    }
}
