/**
 A control is trapped by a disabled fieldset if it is a descendant of any disabled {@code fieldset} within this
 form's ownership, except when it lies within that fieldset's first direct {@code legend} child's subtree. The
 exception applies only to that first legend: other sibling legends, nested fieldsets, and any outer disabled
 fieldset are still enforced.
 */
private static boolean isDisabledFieldsetControl(Element el) {
    Element ancestor = el.parent();
    while (ancestor != null) {
        if (ancestor instanceof FormElement) break; // fieldset disabledness is scoped to the form ownership
        if (ancestor.nameIs("fieldset") && ancestor.hasAttr("disabled")) {
            Element legend = firstLegendChild(ancestor);
            if (legend == null || !isDescendant(el, legend))
                return true; // not exempt via this fieldset's first legend
        }
        ancestor = ancestor.parent();
    }
    return false;
}

