import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
import java.util.List;

public class FormProbe2 {
    static int fails=0;
    static void check(String n,Object e,Object a){boolean ok=String.valueOf(e).equals(String.valueOf(a));System.out.println((ok?"PASS ":"FAIL ")+n+" => "+a+(ok?"":" (expected "+e+")"));if(!ok)fails++;}
    static String join(List<Connection.KeyVal> l){StringBuilder s=new StringBuilder();for(Connection.KeyVal kv:l)s.append(kv).append("&");return s.toString();}
    public static void main(String[] a){
        // external control (form=A) sitting inside disabled fieldset owned by B -> still submits to A
        String h="<form id=A></form>"+
          "<form id=B><fieldset disabled><input name=x value=1 form=A><input name=y value=2></fieldset></form>";
        Document doc=Jsoup.parse(h);
        FormElement A=(FormElement)doc.getElementById("A");
        FormElement B=(FormElement)doc.getElementById("B");
        check("external not trapped by B fieldset","x=1&",join(A.formData()));
        check("B trapped","",join(B.formData()));

        // disabled fieldset that itself points at form A, wrapping external control with no form attr
        String h2="<form id=A></form><fieldset disabled form=A><input name=z value=9></fieldset>";
        // fieldset parser-linked? no; control has no form ancestor -> linkedEls? parser form pointer: null -> not linked. So excluded entirely (ownerless)
        Document d2=Jsoup.parse(h2);
        check("ownerless control not submitted","",join(((FormElement)d2.getElementById("A")).formData()));

        // same but control form=A and fieldset form=A -> trapped
        String h3="<form id=A></form><fieldset disabled form=A><input name=z value=9 form=A></fieldset>";
        Document d3=Jsoup.parse(h3);
        check("matching-owner fieldset traps external","",join(((FormElement)d3.getElementById("A")).formData()));

        // nested disabled fieldset inside enabled, control in first legend of disabled one exempt, sibling legend not
        String h4="<form id=C><fieldset><fieldset disabled>"+
            "<legend><input name=e1 value=1></legend>"+
            "<input name=d1 value=2>"+
            "<legend><input name=e2 value=3></legend>"+
          "</fieldset></fieldset></form>";
        check("nested fs legend","e1=1&",join(((FormElement)Jsoup.parse(h4).getElementById("C")).formData()));

        // optgroup/option malformed nesting: option outside optgroup
        String h5="<form id=D><select name=s multiple><optgroup label=g disabled><option value=in selected></optgroup><option value=out selected><div><option value=deep selected></div></select></form>";
        check("malformed select","s=out&s=deep&",join(((FormElement)Jsoup.parse(h5).getElementById("D")).formData()));

        System.out.println(fails==0?"ALL OK":fails+" FAILURES");
        if(fails>0)System.exit(1);
    }
}
