1	package org.jsoup.nodes;
2	
3	import org.jsoup.Connection;
4	import org.jsoup.Jsoup;
5	import org.jsoup.helper.HttpConnection;
6	import org.jsoup.helper.Validate;
7	import org.jsoup.internal.SharedConstants;
8	import org.jsoup.internal.StringUtil;
9	import org.jsoup.parser.Tag;
10	import org.jsoup.select.Elements;
11	import org.jsoup.select.Evaluator;
12	import org.jsoup.select.Selector;
13	import org.jspecify.annotations.Nullable;
14	
15	import java.util.ArrayList;
16	import java.util.Comparator;
17	import java.util.List;
18	
19	/**
20	 * An HTML Form Element provides ready access to the form fields/controls that are associated with it. It also allows a
21	 * form to easily be submitted.
22	 */
23	public class FormElement extends Element {
24	    private final Elements linkedEls = new Elements();
25	    // contains form submittable elements that were linked during the parse (and due to parse rules, may no longer be a child of this form)
26	    private static final Evaluator submittable = Selector.evaluatorOf(StringUtil.join(SharedConstants.FormSubmitTags, ", "));
27	    // the form-listed elements (HTML spec) that can be associated with a form, either as a descendant or via a form attribute
28	    private static final String[] FormListedTags = {
29	        "button", "fieldset", "input", "keygen", "object", "output", "select", "textarea"
30	    };
31	    private static final Evaluator listed = Selector.evaluatorOf(StringUtil.join(FormListedTags, ", "));
32	    // form-listed elements, anywhere in the document, that carry a form attribute (potential form-owner override)
33	    private static final Evaluator listedWithFormAttr = Selector.evaluatorOf(formListedWithFormAttrQuery());
34	
35	    /**
36	     * Create a new, standalone form element.
37	     *
38	     * @param tag        tag of this element
39	     * @param baseUri    the base URI
40	     * @param attributes initial attributes
41	     */
42	    public FormElement(Tag tag, @Nullable String baseUri, @Nullable Attributes attributes) {
43	        super(tag, baseUri, attributes);
44	    }
45	
46	    private static String formListedWithFormAttrQuery() {
47	        StringBuilder query = new StringBuilder();
48	        for (String tag : FormListedTags) {
49	            if (query.length() > 0) query.append(", ");
50	            query.append(tag).append("[form]");
51	        }
52	        return query.toString();
53	    }
54	
55	    /**
56	     * Get the list of form control elements associated with this form.
57	     * @return form controls associated with this element.
58	     */
59	    public Elements elements() {
60	        // As elements may have been added or removed from the DOM after parse, prepare a new list that unions them:
61	        Elements els = select(submittable); // current form children
62	        for (Element linkedEl : linkedEls) {
63	            if (linkedEl.ownerDocument() != null && !els.contains(linkedEl)) {
64	                els.add(linkedEl); // adds previously linked elements, that weren't previously removed from the DOM
65	            }
66	        }
67	
68	        return els;
69	    }
70	
71	    /**
72	     * Get the form-listed controls currently associated with this form, in final document order. A control is
73	     * associated if it is a descendant of this form, if it was linked to this form by the parser and is not nested in
74	     * another form, or if it carries a {@code form} attribute whose value resolves to this form's id. Controls with a
75	     * {@code form} attribute pointing at another (or no) form, controls nested in another form, detached controls, and
76	     * duplicates are excluded.
77	     */
78	    private Elements associatedControls() {
79	        Document doc = ownerDocument();
80	        Elements controls = new Elements();
81	
82	        // current form descendants (in document order)
83	        for (Element el : select(listed)) {
84	            if (belongsToThisForm(el, doc)) controls.add(el);
85	        }
86	
87	        // parser-linked controls that may live outside of the form (e.g. fostered out of table markup)
88	        if (doc != null) {
89	            for (Element el : linkedEls) {
90	                if (el.ownerDocument() == doc && !controls.contains(el) && belongsToThisForm(el, doc))
91	                    controls.add(el);
92	            }
93	        }
94	
95	        // controls outside of the form, associated by a form="id" attribute
96	        if (doc != null && !id().isEmpty()) {
97	            for (Element el : doc.select(listedWithFormAttr)) {
98	                if (!controls.contains(el) && belongsToThisForm(el, doc))
99	                    controls.add(el);
100	            }
101	        }
102	
103	        // the descendant scan is already in document order; re-sort when out-of-form controls may have been appended
104	        if (doc != null) controls.sort(DocumentOrder);
105	        return controls;
106	    }
107	
108	    /** A listed control belongs to this form if its form attribute resolves to this form; otherwise, if it is nested
109	     * in a form, that form must be this one; otherwise (no form ancestor) it must have been parser-linked to this one. */
110	    private boolean belongsToThisForm(Element el, @Nullable Document doc) {
111	        String formOwner = el.attr("form");
112	        if (!formOwner.isEmpty()) {
113	            return doc != null && doc.getElementById(formOwner) == this;
114	        }
115	        FormElement formAncestor = nearestFormAncestor(el);
116	        if (formAncestor != null) return formAncestor == this;
117	        return linkedEls.contains(el);
118	    }
119	
120	    private static @Nullable FormElement nearestFormAncestor(Element el) {
121	        Node parent = el.parentNode;
122	        while (parent != null) {
123	            if (parent instanceof FormElement) return (FormElement) parent;
124	            parent = parent.parentNode;
125	        }
126	        return null;
127	    }
128	
129	    // compares attached nodes by their position in a pre-order document traversal
130	    private static final Comparator<Element> DocumentOrder = (a, b) -> {
131	        if (a == b) return 0;
132	        ArrayList<Node> aPath = ancestorPath(a);
133	        ArrayList<Node> bPath = ancestorPath(b);
134	        int depth = Math.min(aPath.size(), bPath.size());
135	        for (int i = 0; i < depth; i++) {
136	            Node aAncestor = aPath.get(i);
137	            Node bAncestor = bPath.get(i);
138	            if (aAncestor != bAncestor)
139	                return Integer.compare(aAncestor.siblingIndex(), bAncestor.siblingIndex());
140	        }
141	        return Integer.compare(aPath.size(), bPath.size()); // one is an ancestor of the other
142	    };
143	
144	    private static ArrayList<Node> ancestorPath(Node node) {
145	        ArrayList<Node> path = new ArrayList<>();
146	        Node current = node;
147	        while (current != null) {
148	            path.add(current);
149	            current = current.parentNode;
150	        }
