import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.Connection;
import java.util.List;

public class FormProbe3 {
    static int fails=0;
    static void check(String n,Object e,Object a){boolean ok=String.valueOf(e).equals(String.valueOf(a));System.out.println((ok?"PASS ":"FAIL ")+n+" => ["+a+"]"+(ok?"":" (expected ["+e+"])"));if(!ok)fails++;}
    static String join(List<Connection.KeyVal> l){StringBuilder s=new StringBuilder();for(Connection.KeyVal kv:l)s.append(kv).append("&");return s.toString();}
    public static void main(String[] a){
        // clone retains descendant data, no cross-doc leakage
        FormElement f=(FormElement)Jsoup.parse("<form id=f><input name=x value=1></form><input name=y value=2 form=f>").getElementById("f");
        FormElement c=f.clone();
        check("clone data","x=1&",join(c.formData()));
        c.formData(); f.formData(); // no throw, independent

        // malformed: unclosed select, options after select? duplicate selected on multiple, empty options
        String h1="<form id=a><select name=s><option value=1 selected><option value=2 selected><option selected>";
        check("unclosed single select","s=1&",join(((FormElement)Jsoup.parse(h1).getElementById("a")).formData()));

        String h2="<form id=b><select name=m multiple><option value=1 selected><option value=2 selected><option selected></select></form>";
        check("multiple dup selected + text option","m=1&m=2&m=&",join(((FormElement)Jsoup.parse(h2).getElementById("b")).formData()));

        // nested disabled fieldset in legend: fieldset inside legend disabled
        String h3="<form id=c><fieldset disabled><legend>Leg<fieldset disabled><input name=deep value=1></fieldset></legend><input name=out value=2></fieldset></form>";
        // legend exempts its whole subtree from OUTER disabled fieldset, but inner disabled fieldset still applies
        check("inner fs in legend still enforces","",join(((FormElement)Jsoup.parse(h3).getElementById("c")).formData()));

        // select entirely disabled options -> single falls back nothing
        String h4="<form id=d><select name=s><option disabled>a<option disabled>b</select></form>";
        check("all-disabled single options","",join(((FormElement)Jsoup.parse(h4).getElementById("d")).formData()));

        // optgroup disabled, options without value use text
        String h5="<form id=e><select name=s><optgroup disabled><option selected>ng</optgroup><option>ok</option></select></form>";
        check("disabled optgroup fallback to enabled text option","s=ok&",join(((FormElement)Jsoup.parse(h5).getElementById("e")).formData()));

        // radio group: multiple checked across same name - each checked submits (browsers: parse-time unchecks, but jsoup keeps attrs; spec literal: submit checked)
        String h6="<form id=f2><input type=radio name=r value=1 checked><input type=radio name=r value=2 checked></form>";
        check("two checked radios both kept (attr model)","r=1&r=2&",join(((FormElement)Jsoup.parse(h6).getElementById("f2")).formData()));

        // multiple select without multiple attr => one value
        // textarea keeps value rules
        String h7="<form id=g><textarea name=t></textarea><input type=submit name=go value=Go><button name=btn value=b>x</button></form>";
        check("textarea/submit/button","t=&go=Go&btn=b&",join(((FormElement)Jsoup.parse(h7).getElementById("g")).formData()));

        System.out.println(fails==0?"ALL OK":fails+" FAILURES");
        if(fails>0)System.exit(1);
    }
}
